# Mago.dev: the observer. Appearances 5-6 and the payoff are drafted as real pages (checked by tools/check_dk.py).
def _H(en, pt): return ("atos", en, pt, None, None)
def _X(spk, en, pt): return (spk, en, pt, None, None)
def _N(le, lp, en, pt): return ("narrator", en, pt, le, lp)
